import java.nio.file.Path;
import java.nio.file.SimpleFileVisitor;
import java.nio.file.StandardCopyOption;
import java.nio.file.attribute.BasicFileAttributes;

import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;

/**
 * Minimal stand-in for maven-resources-plugin's resource copying: copies a
 * source resource tree into an output directory. No filtering is applied;
 * the project's resources contain no filter tokens.
 */
public class CopyResourcesMojo extends AbstractMojo {

    /** Injected: ${basedir} */
    private File basedir;

    /** Injected: ${project.build.outputDirectory} or ${project.build.testOutputDirectory} */
    private File outputDirectory;

    /** Injected via plugin.xml default-value: source directory relative to basedir. */
    private String sourceDirectory;

    @Override
    public void execute() throws MojoExecutionException {
        File source = new File(basedir, sourceDirectory);
        if (!source.isDirectory()) {
            getLog().debug("Resource directory " + source + " does not exist, skipping.");
            return;
        }
        final Path sourceRoot = source.toPath();
        final Path targetRoot = outputDirectory.toPath();
        try {
            Files.walkFileTree(sourceRoot, new SimpleFileVisitor<Path>() {
                @Override
                public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs)
                        throws IOException {
                    Files.createDirectories(targetRoot.resolve(sourceRoot.relativize(dir)));
                    return FileVisitResult.CONTINUE;
                }

                @Override
                public FileVisitResult visitFile(Path file, BasicFileAttributes attrs)
                        throws IOException {
                    Files.copy(file, targetRoot.resolve(sourceRoot.relativize(file)),
                            StandardCopyOption.REPLACE_EXISTING);
                    return FileVisitResult.CONTINUE;
                }
            });
        } catch (IOException e) {
