import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;

import javax.tools.Diagnostic;
import javax.tools.DiagnosticCollector;
import javax.tools.JavaCompiler;
import javax.tools.JavaFileObject;
import javax.tools.StandardJavaFileManager;
import javax.tools.ToolProvider;

import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;
import org.apache.maven.plugin.MojoFailureException;

/**
 * Minimal stand-in for maven-compiler-plugin's compile/testCompile goals,
 * delegating to the in-process javax.tools compiler. Used for both goals via
 * different default configuration in plugin.xml.
 */
public class CompilerMojo extends AbstractMojo {

    /** Injected: ${project.compileSourceRoots} or ${project.testCompileSourceRoots} */
    private List<String> compileSourceRoots;

    /** Injected: ${project.compileClasspathElements} or ${project.testClasspathElements} */
    private List<String> classpathElements;

    /** Injected: ${project.build.outputDirectory} or ${project.build.testOutputDirectory} */
    private File outputDirectory;

    /** Injected: ${project.build.sourceEncoding} */
    private String encoding;

    /** Injected: ${maven.compiler.release} */
    private String release;

    /** Injected: ${maven.compiler.parameters} */
    private boolean parameters;

    @Override
    public void execute() throws MojoExecutionException, MojoFailureException {
        List<File> sources = new ArrayList<>();
        if (compileSourceRoots != null) {
            for (String root : compileSourceRoots) {
                Path rootPath = Path.of(root);
                if (!Files.isDirectory(rootPath)) {
                    continue;
                }
                try (Stream<Path> walk = Files.walk(rootPath)) {
                    walk.filter(p -> p.toString().endsWith(".java"))
                            .filter(Files::isRegularFile)
                            .map(Path::toFile)
                            .forEach(sources::add);
                } catch (Exception e) {
                    throw new MojoExecutionException("Failed to scan source root " + root, e);
                }
            }
        }
        outputDirectory.mkdirs();
        if (sources.isEmpty()) {
            getLog().info("No sources to compile");
            return;
        }
        getLog().info("Compiling " + sources.size() + " source files to " + outputDirectory);

        JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
        if (compiler == null) {
            throw new MojoExecutionException("No system Java compiler available (JDK required)");
        }
        DiagnosticCollector<JavaFileObject> diagnostics = new DiagnosticCollector<>();
        StandardJavaFileManager fileManager =
                compiler.getStandardFileManager(diagnostics, null, StandardCharsets.UTF_8);

        List<String> options = new ArrayList<>();
        options.add("-d");
        options.add(outputDirectory.getAbsolutePath());
        options.add("-encoding");
        options.add(encoding != null && !encoding.isBlank() ? encoding : "UTF-8");
        if (parameters) {
            options.add("-parameters");
        }
        if (release != null && !release.isBlank() && !release.contains("${")) {
            options.add("--release");
            options.add(release.trim());
        }
        if (classpathElements != null && !classpathElements.isEmpty()) {
            options.add("-classpath");
            options.add(String.join(File.pathSeparator, classpathElements));
        }

        Iterable<? extends JavaFileObject> units = fileManager.getJavaFileObjectsFromFiles(sources);
        boolean success = compiler.getTask(null, fileManager, diagnostics, options, null, units).call();
        for (Diagnostic<? extends JavaFileObject> diagnostic : diagnostics.getDiagnostics()) {
            String message = diagnostic.getSource() + ":" + diagnostic.getLineNumber() + " "
                    + diagnostic.getMessage(null);
            if (diagnostic.getKind() == Diagnostic.Kind.ERROR) {
                getLog().error(message);
            } else {
                getLog().warn(message);
            }
        }
        if (!success) {
            throw new MojoFailureException("Compilation failed");
        }
    }
}
