@Component
public class JwtUtil {

    @Value("${jwt.secret}")
    private String secret;

    @Value("${jwt.expiration}")
    private long expiration;

    private SecretKey signingKey() {
        return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
    }

    public String generateToken(String username, String role) {
        Date now = new Date();
        return Jwts.builder()
                .subject(username)
                .claim("role", role)
                .issuedAt(now)
                .expiration(new Date(now.getTime() + expiration))
                .signWith(signingKey())
                .compact();
    }

    public boolean validateToken(String token) {
        try {
            Jwts.parser().verifyWith(signingKey()).build().parseSignedClaims(token);
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    public String getUsername(String token) {
        try {
            return Jwts.parser().verifyWith(signingKey()).build()
                    .parseSignedClaims(token).getPayload().getSubject();
        } catch (Exception e) {
            return null;
        }
    }
}

package com.esf.service.security;

import java.nio.charset.StandardCharsets;

import jakarta.servlet.http.HttpServletResponse;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.MediaType;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

import com.esf.service.dto.ApiResponse;
import com.fasterxml.jackson.databind.ObjectMapper;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    private final JwtAuthFilter jwtAuthFilter;

    public SecurityConfig(JwtAuthFilter jwtAuthFilter) {
        this.jwtAuthFilter = jwtAuthFilter;
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        ObjectMapper objectMapper = new ObjectMapper();
        http
                .csrf(csrf -> csrf.disable())
                .sessionManagement(session ->
                        session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers("/api/auth/**").permitAll()
                        .anyRequest().authenticated())
                .exceptionHandling(handling -> handling.authenticationEntryPoint(
                        (request, response, authException) -> {
                            response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
                            response.setContentType(MediaType.APPLICATION_JSON_VALUE);
                            response.setCharacterEncoding(StandardCharsets.UTF_8.name());
                            objectMapper.writeValue(response.getWriter(),
                                    ApiResponse.error(401, "未认证"));
                        }))
                .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class);
        return http.build();
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }

    @Bean
    public AuthenticationManager authenticationManager(AuthenticationConfiguration configuration)
            throws Exception {
        return configuration.getAuthenticationManager();
    }
}

package com.esf.service.service;

import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;

import com.esf.service.dto.LoginRequest;
import com.esf.service.dto.LoginResponse;
import com.esf.service.entity.User;
import com.esf.service.mapper.UserMapper;
import com.esf.service.security.JwtUtil;

@Service
public class AuthService {

    private final UserMapper userMapper;
    private final PasswordEncoder passwordEncoder;
    private final JwtUtil jwtUtil;

    public AuthService(UserMapper userMapper, PasswordEncoder passwordEncoder, JwtUtil jwtUtil) {
        this.userMapper = userMapper;
        this.passwordEncoder = passwordEncoder;
        this.jwtUtil = jwtUtil;
    }

    public LoginResponse login(LoginRequest request) {
        User user = userMapper.findByUsername(request.getUsername());
        if (user == null || !passwordEncoder.matches(request.getPassword(), user.getPassword())) {
            return null;
        }
        String token = *** user.getRole());
        return new LoginResponse(token, user.getUsername(), user.getRole());
    }
}

package com.esf.service.service;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;

import org.springframework.stereotype.Service;

import com.esf.service.entity.Department;
import com.esf.service.mapper.DepartmentMapper;

@Service
public class DepartmentService {

    private final DepartmentMapper departmentMapper;

    public DepartmentService(DepartmentMapper departmentMapper) {
        this.departmentMapper = departmentMapper;
    }

    public Department createDepartment(String name, String orgId) {
        Department department = new Department();
        department.setName(name);
        department.setOrgId(orgId);
        department.setCreatedAt(LocalDateTime.now().truncatedTo(ChronoUnit.SECONDS));
        departmentMapper.insert(department);
        return department;
    }

    public List<Department> listDepartments(String orgId) {
        if (orgId != null && !orgId.isEmpty()) {
            return departmentMapper.findByOrgId(orgId);
        }
        return departmentMapper.findAll();
    }
}

package com.esf.service.service;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoUnit;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

import org.springframework.stereotype.Service;

import com.esf.service.dto.PageResult;
import com.esf.service.dto.ServiceOrderRequest;
import com.esf.service.dto.ServiceQueryParams;
import com.esf.service.entity.ServiceOrder;
import com.esf.service.mapper.ServiceOrderMapper;

@Service
public class ServiceOrderService {

    private static final DateTimeFormatter SERVICE_ID_TIME_FORMAT =
            DateTimeFormatter.ofPattern("yyyyMMddHHmmss");

    private final ServiceOrderMapper serviceOrderMapper;
    private final AtomicInteger serviceIdSequence = new AtomicInteger(0);

    public ServiceOrderService(ServiceOrderMapper serviceOrderMapper) {
        this.serviceOrderMapper = serviceOrderMapper;
    }

    public ServiceOrder createOrder(ServiceOrderRequest request) {
        ServiceOrder order = new ServiceOrder();
        order.setServiceId(generateServiceId());
        order.setCustomerName(request.getCustomerName());
        order.setOwner(null);
        order.setStatus("PENDING");
        order.setBizType(request.getBizType() != null ? request.getBizType() : "CONSULT");
        order.setPriority(request.getPriority() != null ? request.getPriority() : "P2");
        order.setSourceChannel(request.getSourceChannel() != null ? request.getSourceChannel() : "WEB");
        order.setRegion(request.getRegion() != null ? request.getRegion() : "EAST");
        order.setProductLine(request.getProductLine());
        order.setContactName(request.getContactName());
        order.setSlaLevel(request.getSlaLevel());
        order.setOrgId(request.getOrgId());
        order.setDepartmentId(request.getDepartmentId());
        order.setSkillGroupId(request.getSkillGroupId());
        order.setDescription(request.getDescription());
        LocalDateTime now = LocalDateTime.now().truncatedTo(ChronoUnit.SECONDS);
        order.setCreatedAt(now);
        order.setUpdatedAt(now);
        serviceOrderMapper.insert(order);
        return order;
    }

    public ServiceOrder getById(Long id) {
        return serviceOrderMapper.findById(id);
    }

    public PageResult<ServiceOrder> queryOrders(ServiceQueryParams params) {
        int current = params.getCurrent() != null ? params.getCurrent() : 1;
        int size = params.getSize() != null ? params.getSize() : 10;
        int offset = (current - 1) * size;
        List<ServiceOrder> records = serviceOrderMapper.queryList(params, offset, size);
        long total = serviceOrderMapper.queryCount(params);
        return new PageResult<>(records, total, current, size);
    }

    public Map<String, Object> updateStatus(Long id, String status, String owner) {
        ServiceOrder existing = serviceOrderMapper.findById(id);
        if (existing == null) {
            return null;
        }
        serviceOrderMapper.updateStatus(id, status, owner, LocalDateTime.now().truncatedTo(ChronoUnit.SECONDS));
        Map<String, Object> result = new LinkedHashMap<>();
        result.put("id", id);
        result.put("status", status);
        result.put("owner", owner);
        return result;
    }

    public Map<String, Long> getStats(String orgId) {
        boolean scoped = orgId != null && !orgId.isEmpty();
        Map<String, Long> stats = new LinkedHashMap<>();
        stats.put("total", scoped ? serviceOrderMapper.countByOrgId(orgId) : serviceOrderMapper.countAll());
        stats.put("pending", countByStatus(scoped, orgId, "PENDING"));
        stats.put("inProgress", countByStatus(scoped, orgId, "IN_PROGRESS"));
        stats.put("completed", countByStatus(scoped, orgId, "COMPLETED"));
        stats.put("cancelled", countByStatus(scoped, orgId, "CANCELLED"));
        return stats;
    }

    private long countByStatus(boolean scoped, String orgId, String status) {
        return scoped ? serviceOrderMapper.countByOrgIdAndStatus(orgId, status)
                : serviceOrderMapper.countByStatus(status);
    }

    private String generateServiceId() {
        return "P" + LocalDateTime.now().format(SERVICE_ID_TIME_FORMAT)
                + String.format("%06d", serviceIdSequence.incrementAndGet());
    }
}
